+          </TableRow>
+        </TableHeader>
+        <TableBody>
+          {OPTIONAL_DEPENDENCIES.map((dep) => {
+            const isInstalled = dep.packagesRequired.every((pkg) =>
+              installedPackageNames.has(pkg.name.split("[")[0]),
+            );
+            const packageSpec = dep.packagesRequired
+              .map((pkg) => pkg.name)
+              .join(", ");
+
+            return (
